package com.crosscheck.model;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="audit_logs") public class AuditLog{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String userName; private String action; private String entityType; private String entityId; @Column(length=1000) private String details; private LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public String getUserName(){return userName;} public void setUserName(String v){userName=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getEntityType(){return entityType;} public void setEntityType(String v){entityType=v;} public String getEntityId(){return entityId;} public void setEntityId(String v){entityId=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public LocalDateTime getCreatedAt(){return createdAt;}}
